INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.119.0',
  '2026-10-15',
  'Tracker: сутки начинаются когда встанешь, несколько отметок в день и напоминания, которые не отстают',
  E'Сутки у трекера больше не обязаны переключаться в полночь. В настройках категории появилось «День начинается в»: при 05:00 отметка, поставленная в час ночи, относится к предыдущему дню — так, как считает человек, а не календарь. Это нужно там, где отмечаться надо дважды, днём и ночью: обе отметки попадают в один день. «Сегодня» в сетке недель, в календаре и во всей истории теперь тоже день трекера, а не календарная дата.\n\nРядом — «Отметок в день». Клетка, где отметок уже есть, но до нормы не хватает, рисуется бледнее, а цифра в ней говорит, сколько набрано.\n\nГалочка «Спамить при незаполнении» заставляет бота не ограничиваться одним сообщением: пока отметок не хватает, он напоминает каждые N минут (по умолчанию десять), но не больше двадцати раз за день. В тихие часы повторы молчат и после них не высыпаются пачкой. Надоело раньше времени — кнопка 🔕 у названия трекера выключает напоминания до конца дня, 🔔 возвращает. У общего трекера отметки общие, а глушилка у каждого своя: терпение у людей разное.\n\nУ напоминания «по привычке» в Reminders появилось поле «Отметок должно быть к этому времени». Для двух отметок в сутки делается два напоминания: дневному хватит одной отметки, ночному нужны обе.',
  E'Миграция 0172: на tracker_categories — day_start_minutes, daily_target, spam_minutes, spam_max; на reminders — expect_marks, spam_sent, spam_day; новая таблица tracker_hushes (PK category_id+user_id+day).\n\nДень трекера считает одна функция на обе стороны: store.TrackerDay и trackerDay в dates.ts — сдвиг назад на day_start_minutes в таймзоне пользователя. Порог сравнивается «не меньше чем» (MarksOnDay >= expect_marks): отдельных слотов под «дневную» и «ночную» отметку нет, клик по клетке счётчика остался прежним (+1 / −1 долгим нажатием).\n\nЦикл повторов живёт на самом напоминании: spam_sent — сколько сообщений уже ушло, spam_day — для какого дня трекера идёт цикл. Непустой spam_day означает «цикл жив», и по нему воркер отличает повтор от прихода по расписанию — иначе срабатывание на следующий день путалось бы с остатком вчерашнего цикла. Сменился день трекера на повторе — цикл бросается молча. В тихие часы повтор пропускается (цикл держится, проверка через X минут), а НЕ ложится в notify_queue: иначе после тишины прилетело бы двадцать сообщений сразу.\n\nГлушилка персональная, потому что tracker_marks не имеет измерения пользователя — отметки у расшаренного трекера физически общие, а напоминания у каждого свои (reminders.user_id). Выключение повторов в PATCH категории едет отдельным флагом spam_off: null в патче значит «не трогать».\n\nПроверено на одноразовой базе с реальным воркером: первый приход с прогрессом «0 из 2», три повтора по spam_max и возврат к расписанию, молчание при достаточных отметках, молчание под 🔕, брошенный цикл при смене дня и пропуск повтора в тихие часы без потери счётчика.'
);
-- +goose StatementEnd

